   'shell-when':()=>flow('板厚方向の応力分布をどこまで求めるかでモデルを選びます。',['薄い板','中立面と板厚'],['板厚方向の詳細','局所接触や層間応力'],['評価の選択','必要に応じて立体要素']),
   'shell-input':()=>flow('同じ場所に点を置くことと、どの順番で面を作るかは別の指定です。',['GRID','位置を定義する'],['CQUAD4／CTRIA3','外周に沿う順で節点を指定'],['PSHELL','PIDで板厚・材料を指定']),
   'shell-pshell':()=>flow('板の剛性は、どの変形を受け持つかで材料参照が分かれます。',['MID1','面内の膜剛性'],['MID2','面外曲げ剛性'],['MID3／MID4','横せん断／膜と曲げの連成']),
   'shell-output':()=>flow('単位幅の力やモーメントと、表裏で読む応力を分けます。',['膜力','力／幅'],['曲げモーメント','モーメント／幅'],['応力','厚さ方向の評価位置']),
   'shell-plate2':()=>flow('単位幅で出力された量から、評価する幅全体の力を求めます。',['軸方向の膜力','力／幅で読む'],['曲げモーメント','モーメント／幅で読む'],['評価する幅','単位幅の値に幅を掛ける']),
   'shell-strain2':()=>flow('基準面の伸びと曲率から、上下の評価位置のひずみを求めます。',['中央面','面内ひずみ'],['曲率','表裏で逆符号の寄与'],['表裏のひずみ','中央面＋距離に比例する項']),
